				return fmt.Errorf("snapshot progress %d is already running", p.ProgressID)
			}

			res := tx.Exec(`
				UPDATE cdc_system.snapshot_progress
				SET status = 'running',
				    trace_id = ?,
				    error_msg = NULL,
				    updated_at = NOW()
				WHERE id = ? AND status IN ('paused', 'error')
			`, p.TraceID, p.ProgressID)
			if res.Error != nil {
				return res.Error
			}
			if res.RowsAffected == 0 {
				return fmt.Errorf("failed to claim progress %d: status is not paused or error", p.ProgressID)
			}

